// Server bank — SEED test (supabase/pilot-seed.sql).
// The seed file is generated by scripts/seed-server-bank.js from the
// REAL math-ntuc bank. This test proves the generated file is what
// it claims to be: exactly the 44 real bank stems, no duplicates,
// valid rows, and — for the maths check — the recompute outcome is
// exactly the documented one (see below).
//
// Honest note: NOT all 44 stems recompute under the live-gen
// validator, and that is CORRECT. The validator is a live-generation
// gate, not a bank-correctness check — these are hand-checked bank
// questions, and the 11 that fail do so for known, legitimate
// reasons:
//  - 7x 'too-few-numbers': the quantity is written as a WORD ("One
//    carton…", "Six bags…"), so the digit extractor sees only one
//    number. The question is fine for a child; the validator just
//    cannot see word-numbers.
//  - 5x 'non-computable-type': P4 estimation / multiples / factors
//    ("Estimate…", "Which number is a multiple…"). Legitimate P4 MOE
//    content that the recompute validator rejects by design.
// (The watermelon change question used to fail here too — the
// validator only tried pairs in stem order — but the reverse-order
// fix of 2026-11-08 makes it recompute now, so it is no longer in
// the failing set. The test pins this exact set: any NEW failure (a
// genuinely wrong bank answer) fails the test.
'use strict';
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const SEED_PATH = path.join(__dirname, '..', 'supabase', 'pilot-seed.sql');
const PAGE_PATH = path.join(__dirname, '..', 'public', 'index.html');
const html = fs.readFileSync(PAGE_PATH, 'utf8');

function Q(q, o, a, c, j) { return { q, o, a, c, j }; }
function extractVar(src, name) {
  const s = src.indexOf('var ' + name + '=');
  let i = src.indexOf('=', s) + 1, depth = 0, inStr = false, strCh = '', esc = false;
  const start = i;
  for (; i < src.length; i++) {
    const ch = src[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === strCh) inStr = false; continue; }
    if (ch === '"' || ch === "'") { inStr = true; strCh = ch; continue; }
    if (ch === '[' || ch === '{') depth++;
    if (ch === ']' || ch === '}') { depth--; if (depth === 0) return src.slice(start, i + 1); }
  }
  throw new Error('no end ' + name);
}

// Parse one INSERT line's VALUES list: 10 literals in fixed order
// (id, topic, level, sub_topic, stem, options, answer, explanation,
// joke, source). Single quotes escape as ''.
function parseInsert(line) {
  const at = line.indexOf('values (');
  assert.ok(at >= 0, 'no VALUES in: ' + line.slice(0, 80));
  let i = at + 'values ('.length;
  const vals = [];
  while (vals.length < 10) {
    while (line[i] === ' ' || line[i] === ',') i++;
    if (line[i] === "'") {
      let s = '';
      i++;
      while (i < line.length) {
        if (line[i] === "'") {
          if (line[i + 1] === "'") { s += "'"; i += 2; continue; }
          i++;
          break;
        }
        s += line[i];
        i++;
      }
      vals.push(s);
    } else {
      let s = '';
      while (i < line.length && line[i] !== ',' && line[i] !== ')') { s += line[i]; i++; }
      vals.push(s.trim());
    }
  }
  return {
    id: vals[0], topic: vals[1], level: parseInt(vals[2], 10), sub_topic: vals[3],
    stem: vals[4], options: JSON.parse(vals[5]), answer: parseInt(vals[6], 10),
    explanation: vals[7], joke: vals[8], source: vals[9],
  };
}

const EXPECTED_FAILURES = [
  { stem: 'One carton of milk is $2. Three cartons cost…', reason: 'too-few-numbers' },
  { stem: 'One carton of juice is $3.50. Two cartons cost…', reason: 'too-few-numbers' },
  { stem: 'One apple costs $0.90. Six apples cost…', reason: 'too-few-numbers' },
  { stem: '100 cents = $___', reason: 'too-few-numbers' },
  { stem: 'Oranges in bags of 5. Six bags hold…', reason: 'too-few-numbers' },
  { stem: 'One bottle of juice is $3. Two bottles cost…', reason: 'too-few-numbers' },
  { stem: 'Which number is a multiple of both 4 and 6?', reason: 'non-computable-type' },
  { stem: 'Estimate: 48 × 5 is closest to…', reason: 'non-computable-type' },
  { stem: 'Which of these is a factor of 24?', reason: 'non-computable-type' },
  { stem: 'What is the smallest multiple of 8 that is more than 50?', reason: 'non-computable-type' },
  { stem: 'Estimate: 298 + 405 is about…', reason: 'non-computable-type' },
];

test('server-bank seed: exactly the 44 real bank stems, no duplicates, valid rows', () => {
  const sql = fs.readFileSync(SEED_PATH, 'utf8');
  assert.match(sql, /GENERATED by scripts\/seed-server-bank\.js/, 'seed file says it is generated');
  const lines = sql.split('\n').filter((l) => l.indexOf('insert into public.sb_questions') === 0);
  assert.equal(lines.length, 44, 'one INSERT per question');
  const rows = lines.map(parseInsert);
  assert.equal(new Set(rows.map((r) => r.id)).size, 44, 'ids are unique');
  assert.deepEqual(
    rows.map((r) => r.id),
    [].concat(
      Array.from({ length: 29 }, (_, i) => 'math-ntuc-p3-' + String(i + 1).padStart(4, '0')),
      Array.from({ length: 15 }, (_, i) => 'math-ntuc-p4-' + String(i + 1).padStart(4, '0'))
    ),
    'stable ids: p3-0001..0029 then p4-0001..0015, in bank order'
  );
  const byLevel = { 3: rows.filter((r) => r.level === 3), 4: rows.filter((r) => r.level === 4) };
  assert.equal(byLevel[3].length, 29, 'P3: quest 5 + fresh 10 + warm 8 + retry 6');
  assert.equal(byLevel[4].length, 15, 'P4: quest 5 + fresh 10');
  assert.deepEqual(byLevel[3].map((r) => r.sub_topic).reduce((acc, k) => { acc[k] = (acc[k] || 0) + 1; return acc; }, {}), { quest: 5, fresh: 10, warm: 8, retry: 6 });
  assert.deepEqual(byLevel[4].map((r) => r.sub_topic).reduce((acc, k) => { acc[k] = (acc[k] || 0) + 1; return acc; }, {}), { quest: 5, fresh: 10 });
  rows.forEach((r) => {
    assert.equal(r.topic, 'math-ntuc');
    assert.equal(r.source, 'bank');
    assert.ok(Array.isArray(r.options) && r.options.length === 4, r.id + ': 4 options');
    assert.ok(Number.isInteger(r.answer) && r.answer >= 0 && r.answer <= 3, r.id + ': valid answer index');
    assert.ok(typeof r.stem === 'string' && r.stem.length > 0, r.id + ': stem present');
    assert.ok(typeof r.explanation === 'string', r.id + ': explanation is a string');
  });
  assert.ok(lines.every((l) => l.indexOf('on conflict (id) do nothing;') >= 0), 'inserts are idempotent');

  // The stems are the real bank stems — same extraction as the
  // live-gen tests (TOPICS + FRESH_BANK, 44 stems).
  const TOPICS = eval('(' + extractVar(html, 'TOPICS') + ')');
  const FRESH = eval('(' + extractVar(html, 'FRESH_BANK') + ')');
  const NTUC = TOPICS.find((t) => t.id === 'math-ntuc');
  const bank44 = [...NTUC.quest, ...FRESH['math-ntuc'], ...NTUC.warm, ...NTUC.retry, ...NTUC.p4quest, ...NTUC.p4fresh];
  assert.equal(bank44.length, 44);
  const { liveGenNormStem } = require('../lib/live-gen');
  const bankStems = bank44.map((q) => liveGenNormStem(q.q)).sort();
  const seedStems = rows.map((r) => liveGenNormStem(r.stem)).sort();
  assert.deepEqual(seedStems, bankStems, 'seed stems match the real bank stems exactly');
  assert.equal(new Set(seedStems).size, 44, 'no duplicate stems in the seed');
  // Options and answers match the bank too (same order as the bank).
  const bankByStem = {};
  bank44.forEach((q) => { bankByStem[liveGenNormStem(q.q)] = q; });
  rows.forEach((r) => {
    const b = bankByStem[liveGenNormStem(r.stem)];
    assert.deepEqual(r.options, b.o, r.id + ': options match the bank');
    assert.equal(r.answer, b.a, r.id + ': answer index matches the bank');
    assert.equal(r.explanation, b.c || '', r.id + ': explanation matches the bank');
    assert.equal(r.joke, b.j || '', r.id + ': joke matches the bank');
  });
});

test('server-bank seed: recompute outcome is exactly the documented set (33 pass, 11 known)', () => {
  const { liveGenNormStem, liveGenOptNum, liveGenRecompute } = require('../lib/live-gen');
  const sql = fs.readFileSync(SEED_PATH, 'utf8');
  const rows = sql.split('\n').filter((l) => l.indexOf('insert into public.sb_questions') === 0).map(parseInsert);
  const failures = [];
  rows.forEach((r) => {
    const ans = liveGenOptNum(r.options[r.answer]);
    const rc = liveGenRecompute(r.stem, ans);
    if (!rc.ok) failures.push({ stem: liveGenNormStem(r.stem), reason: rc.reason });
  });
  const expected = EXPECTED_FAILURES.map((f) => ({ stem: liveGenNormStem(f.stem), reason: f.reason }));
  const byStem = (list) => list.slice().sort((a, b) => (a.stem < b.stem ? -1 : 1));
  assert.equal(failures.length, 11, '11 of 44 do not recompute — and they are the documented 11, nothing else');
  assert.deepEqual(byStem(failures), byStem(expected), 'the failing stems and reasons match the documented list exactly');
  assert.equal(rows.length - failures.length, 33, 'the other 33 recompute cleanly');
});
